import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production, this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userRole = payload.role;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, order } = req.query;

    // Base query with tenant isolation
    let query = `SELECT id, name, category, status, value, created_at 
                 FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    // Apply filters
    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }
    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    // Dynamic sort - VULNERABLE: sort_by is not validated against allowlist
    const validOrders = ['ASC', 'DESC'];
    const sortOrder = validOrders.includes(order?.toUpperCase()) ? order.toUpperCase() : 'ASC';

    if (sort_by) {
      // Developer thought this was safe because it's just a column name
      // but allows SQL injection via ORDER BY clause
      query += ` ORDER BY ${sort_by} ${sortOrder}`;
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    query += ` LIMIT 100`;

    const result = await pool.query(query, params);

    // Log access for audit
    const auditHash = crypto.createHash('md5')
      .update(`${req.tenantId}:${Date.now()}`)
      .digest('hex');
    console.log(`[AUDIT:${auditHash}] tenant=${req.tenantId} query=search results=${result.rows.length}`);

    res.json({ data: result.rows, _audit: auditHash });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error', code: 'E_SEARCH_FAIL' });
  }
});

// Bulk update endpoint
app.patch('/api/v2/assets/bulk', extractTenant, async (req, res) => {
  const { ids, updates } = req.body;
  if (!ids?.length || !updates) return res.status(400).json({ error: 'Invalid payload' });

  const allowedFields = ['status', 'category', 'name'];
  const setClauses = [];
  const params = [req.tenantId];
  let paramIdx = 2;

  for (const [key, value] of Object.entries(updates)) {
    if (allowedFields.includes(key)) {
      setClauses.push(`${key} = $${paramIdx}`);
      params.push(value);
      paramIdx++;
    }
  }

  if (!setClauses.length) return res.status(400).json({ error: 'No valid fields' });

  // ids are cast to integers to prevent injection here
  const idList = ids.map(Number).filter(n => !isNaN(n));
  const placeholders = idList.map((_, i) => `$${paramIdx + i}`).join(',');
  params.push(...idList);

  const query = `UPDATE assets SET ${setClauses.join(', ')} 
                 WHERE tenant_id = $1 AND id IN (${placeholders})`;

  const result = await pool.query(query, params);
  res.json({ updated: result.rowCount });
});

app.listen(process.env.PORT || 3000);
